-- ----------------------------------------------------------------
-- NPC texts take the values of the retail 15595 sniffs.
--
-- Texts, languages, probabilities and emotes of the 2,296 texts sniffed on
-- build 15595 (the Cataclysm Preservation Project's world database) take the
-- sniff's values where the client would see a difference, and the five
-- sniffed texts we lacked are added.
--
-- Many of our texts held an emote in the delay column and 0 in the emote
-- column, which plays nothing; retail data has that pair once in about
-- 1,400. On texts no sniff covers, such a pair is turned back when its delay
-- is an emote id of the client's Emotes.dbc. An empty option's language the
-- client's Languages.dbc does not have becomes 0.
-- ----------------------------------------------------------------
DROP PROCEDURE IF EXISTS `update_mangos`;

DELIMITER $$

CREATE PROCEDURE `update_mangos`()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SHOW ERRORS;
        SELECT '* UPDATE FAILED *' AS `===== Status =====`,
               @cCurResult AS `===== DB is on Version: =====`;
        RESIGNAL;
    END;

    SET @cCurVersion := (SELECT `version` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurStructure := (SELECT `structure` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurContent := (SELECT `content` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);

    SET @cOldVersion = '22';
    SET @cOldStructure = '11';
    SET @cOldContent = '004';

    SET @cNewVersion = '22';
    SET @cNewStructure = '11';
    SET @cNewContent = '005';
    SET @cNewDescription = 'Npc_Text_Values';
    SET @cNewComment = 'NPC texts take the values of the retail 15595 sniffs';

    SET @cCurResult := (SELECT `description` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cOldResult := (SELECT `description` FROM `db_version` WHERE `version` = @cOldVersion AND `structure` = @cOldStructure AND `content` = @cOldContent);
    SET @cNewResult := (SELECT `description` FROM `db_version` WHERE `version` = @cNewVersion AND `structure` = @cNewStructure AND `content` = @cNewContent);

    IF (@cCurResult = @cOldResult) THEN
        START TRANSACTION;

        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 3 WHERE `ID` = 24;
        UPDATE `npc_text` SET `em2_0_delay` = 0, `em2_0` = 3 WHERE `ID` = 48;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 141;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 6 WHERE `ID` = 153;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 185;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 396 WHERE `ID` = 194;
        UPDATE `npc_text` SET `text0_0` = 'I used to direct Steamwheedle''s shredder development program, but last month I struck out on my own. Now all my suppliers have blacklisted me. Worse, my development efforts haven''t even gotten off the ground yet. I could use your help, $n!', `text0_1` = '' WHERE `ID` = 519;
        UPDATE `npc_text` SET `text0_0` = 'I figured I would step up my research efforts by, uh, ''borrowing'' some technology from the Venture Company. See, their new shredder is best of breed, from the interchangeable hands to the control grips!$B$BMy business partner Wizzlecrank is west of here in the Sludge Fen doing some ''Field Research'' for me, but he hasn''t gotten back yet. ', `text0_1` = '' WHERE `ID` = 520;
        UPDATE `npc_text` SET `text0_0` = 'Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.', `text0_1` = 'Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.' WHERE `ID` = 539;
        UPDATE `npc_text` SET `text0_0` = 'Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.', `text0_1` = 'Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.' WHERE `ID` = 559;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 562;
        UPDATE `npc_text` SET `text0_0` = 'Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.', `text0_1` = 'Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.' WHERE `ID` = 563;
        UPDATE `npc_text` SET `text0_0` = 'Greetin''s, $c.  I be pityin'' your kind, for de secrets of true magic are beyond ya...', `text0_1` = 'Greetin''s, $c.  I be pityin'' your kind, for de secrets of true magic are beyond ya...', `em0_0_delay` = 0, `em0_0` = 274 WHERE `ID` = 565;
        UPDATE `npc_text` SET `text0_0` = 'The Shattered Hand will see the Horde to their former glory.', `text0_1` = 'The Shattered Hand will see the Horde to their former glory.' WHERE `ID` = 638;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 22 WHERE `ID` = 738;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 767;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 768;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 6 WHERE `ID` = 878;
        UPDATE `npc_text` SET `text0_0` = 'With the destruction of Stormwind''s park - and most of the night elves within, the poor, unlucky souls - your best bet would be to seek out old Celestine just outside the Dwarven District.$B$BThere are stairs leading down from the Northern Landing... you can see her cottage from there.', `text0_1` = 'With the destruction of Stormwind''s park - and most of the night elves within, the poor, unlucky souls - your best bet would be to seek out old Celestine just outside the Dwarven District.$B$BThere are stairs leading down from the Northern Landing... you can see her cottage from there.', `text1_0` = '', `text1_1` = '', `lang1` = 0, `prob1` = 0, `text2_0` = '', `text2_1` = '', `lang2` = 0, `prob2` = 0 WHERE `ID` = 902;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 6 WHERE `ID` = 907;
        UPDATE `npc_text` SET `lang0` = 0 WHERE `ID` = 933;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 934;
        UPDATE `npc_text` SET `text0_0` = 'Are you here for training?  Or are you just here to waste a warrior''s time?', `text0_1` = 'Are you here for training?  Or are you just here to waste a warrior''s time?' WHERE `ID` = 1040;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 1138;
        UPDATE `npc_text` SET `text0_0` = 'Sul''thraze... the first time I heard the word uttered I was around your age. It meant nothing to me then, as it means nothing to you now. It was not until a warband of trolls coming from Zul''Farrak laid waste to the land that I understood... and feared.$B$BMany will tell you that the Splitblade of Suffering does not exist. That it''s a myth; a rumor started to scare children. But believe me, $r, it exists.$B$B<Trenton loses focus as he runs his hand across the jagged scar on his face.>', `text0_1` = '' WHERE `ID` = 1758;
        UPDATE `npc_text` SET `text0_0` = 'The humans built an inn on the edge of the Barrens. The Shady Rest, they called it. Weeks ago, it was burned down.$b$bWhy do I care? I don''t-not about the humans anyway-but I had a spy placed in that inn and I will not let his death go unanswered. I need to know who did this.$B$BIf you wish to provide assistance, go to the remains of the Shady Rest Inn and return any clues you find to me.', `text0_1` = '' WHERE `ID` = 1819;
        UPDATE `npc_text` SET `text0_0` = 'When you stay at an inn, you rest very comfortably.  Because of this, you will become "well rested" much more quickly than you would in the wilderness.  When you are well rested, you learn more from experience.$B$BYou may also speak with any innkeeper to get a hearthstone, and can later use the hearthstone in order to quickly return to that inn.', `text0_1` = 'When you stay at an inn, you rest very comfortably.  Because of this, you will become "well rested" much more quickly than you would in the wilderness.  When you are well rested, you learn more from experience.$B$BYou may also speak with any innkeeper to get a hearthstone, and can later use the hearthstone in order to quickly return to that inn.' WHERE `ID` = 1853;
        UPDATE `npc_text` SET `prob0` = 1 WHERE `ID` = 1921;
        UPDATE `npc_text` SET `prob0` = 1 WHERE `ID` = 1922;
        UPDATE `npc_text` SET `text0_0` = 'Greetings!  If you are here to access goblin engineering schemata, please know we only interface with certified goblin engineers.', `text0_1` = '' WHERE `ID` = 2133;
        UPDATE `npc_text` SET `text0_0` = 'Greetings!  If you are here to access gnome engineering schemata, then you are welcome to do so.  Our scanners report you are a certified gnomish engineer!', `text0_1` = '', `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 2134;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 2236;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 2237;
