        UPDATE `npc_text` SET `lang1` = 0, `lang4` = 0, `lang5` = 0 WHERE `ID` = 2355;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 16 WHERE `ID` = 2473;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 6 WHERE `ID` = 2475;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 6 WHERE `ID` = 2476;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 2477;
