        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 2479;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 2480;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 2481;
        UPDATE `npc_text` SET `prob0` = 0, `prob1` = 0, `text2_0` = 'I will mark the location upon your map.', `text2_1` = 'I will mark the location upon your map.', `prob2` = 1, `em2_0_delay` = 0, `em2_0` = 396 WHERE `ID` = 2500;
        UPDATE `npc_text` SET `prob0` = 0, `prob1` = 0, `text2_0` = 'I will mark the location upon your map.', `text2_1` = 'I will mark the location upon your map.', `prob2` = 1, `em2_0_delay` = 0, `em2_0` = 396 WHERE `ID` = 2502;
        UPDATE `npc_text` SET `text0_0` = 'The Valley of Strength''s bank is south of the entrance to Grommash Hold, northwest of the main gate.', `text0_1` = 'The Valley of Strength''s bank is south of the entrance to Grommash Hold, northwest of the main gate.', `prob0` = 1, `text1_0` = '', `text1_1` = '', `lang1` = 0, `prob1` = 0 WHERE `ID` = 2554;
