        UPDATE `npc_text` SET `prob0` = 0, `prob1` = 0, `text2_0` = 'I will mark the location upon your map.', `text2_1` = 'I will mark the location upon your map.', `prob2` = 1, `em2_0_delay` = 0, `em2_0` = 396 WHERE `ID` = 2562;
        UPDATE `npc_text` SET `prob0` = 0, `prob1` = 0, `text2_0` = 'I will mark the location upon your map.', `text2_1` = 'I will mark the location upon your map.', `prob2` = 1, `em2_0_delay` = 0, `em2_0` = 396 WHERE `ID` = 2563;
        UPDATE `npc_text` SET `em2_1_delay` = 0, `em2_1` = 1, `em5_1_delay` = 0, `em5_1` = 11 WHERE `ID` = 2634;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 2694;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 2695;
        UPDATE `npc_text` SET `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 2696;
        UPDATE `npc_text` SET `text0_0` = 'Do ye have some new treasures that ye want to keep safe n'' sound?  Then ye''ll be wanting to store them at The Vault with the Stonemantles.  \n\nYe''ll find The Vault just a hammer''s throw northeast from the entrance to Ironforge.', `text0_1` = 'Do ye have some new treasures that ye want to keep safe n'' sound?  Ye''ll be wanting to store them at The Vault with the Stonemantles.  Ye''ll find The Vault just a hammer''s throw northeast from the entrance to Ironforge.' WHERE `ID` = 2761;
        UPDATE `npc_text` SET `text0_0` = 'Looking to take a ride on a gryphon, now are ye?  Gryth Thurden is the one ye''ll want to be seeing about that.  \n\nYe can find him on the eastern side of The Great Forge in the middle of Ironforge.', `text0_1` = 'Looking to take a ride on a gryphon, now are ye?  Gryth Thurden is the one ye''ll want to be seeing about that.  \n\nYe can find him on the eastern side of The Great Forge in the middle of Ironforge.', `text1_0` = 'Ah, nothing quite like a ride on a gryphon, is there?  The night elves can keep those hippo''s of theirs, just give me a gryphon and the wind in me hair!  \n\nWell now, I won''t keep ye any longer, just head over to Gryth Thurden on the east side of The Great Forge and he''ll get ye on yer way.', `text1_1` = 'Ah, nothing quite like a ride on a gryphon, is there?  The night elves can keep those hippo''s of theirs, just give me a gryphon and the wind in me hair!  \n\nWell now, I won''t keep ye any longer, just head over to Gryth Thurden on the east side of The Great Forge and he''ll get ye on yer way.' WHERE `ID` = 2762;
        UPDATE `npc_text` SET `text1_0` = 'Bah!  Mailboxes...  all I get is junk mail lately!  \n\nIncrease the size of this... decrease the size of that... act now for your free Sword of Dragonslaying.  I have to change my mailbox number every other month!  \n\nWell, ye can''t say I didn''t warn ye.  If you''re looking for the mailbox it''s just outside the Stonefire Tavern.', `text1_1` = 'Bah!  Mailboxes...  all I get is junk mail lately!  \n\nIncrease the size of this... decrease the size of that... act now for your free Sword of Dragonslaying.  I have to change my mailbox number every other month!  \n\nWell, ye can''t say I didn''t warn ye.  If you''re looking for the mailbox it''s just outside the Stonefire Tavern.' WHERE `ID` = 2769;
        UPDATE `npc_text` SET `text0_0` = 'That wee wizardly lass, Bink, over in the Hall of Mysteries would probably be able to help ye out with any magical needs you have.  \n\nThe Hall of Mysteries is just north of the gates of Ironforge.', `text0_1` = 'That wee wizardly lass, Bink, over in the Hall of Mysteries would probably be able to help ye out with any magical needs you have.\n\nThe Hall of Mysteries is just north of the gates of Ironforge.' WHERE `ID` = 2771;
        UPDATE `npc_text` SET `text0_0` = 'Ah, Braenna Flintcrag.  She has magic hands, that one.  Braenna is the one to see about Priestly matters.  \n\nYe''ll want to travel north from the gates of Ironforge to the Hall of Mysteries.  That''s where ye''ll find her.', `text0_1` = 'Ah, Braenna Flintcrag.  She has magic hands, that one.  Braenna is the one to see about Priestly matters.  \n\nYe''ll want to travel north from the gates of Ironforge to the Hall of Mysteries.  That''s where ye''ll find her.' WHERE `ID` = 2772;
        UPDATE `npc_text` SET `text1_0` = 'All the roguish types hang out in The Forlorn Cavern, north of the gates of Ironforge.  I''d wager ye''ll find Fenthwick there, no doubt counting the coin of another cut purse.  I''ll catch him one of these days!  \n\nIn the meantime I''ll have my eye on you as well, $glad : lass;.', `text1_1` = 'All the roguish types hang out in The Forlorn Cavern, north of the gates of Ironforge.  I''d wager ye''ll find Fenthwick there, no doubt counting the coin of another cut purse.  I''ll catch him one of these days!  \n\nIn the meantime I''ll have my eye on you as well, $glad : lass;.' WHERE `ID` = 2774;
        UPDATE `npc_text` SET `text1_0` = 'A warlock, eh...  Well, if you''ve got a mind to be doing that sort of thing around here then ye best keep yer demons on a leash $gboyo : girlie;.  I don''t like demons, but I love putting mah axe to them.  Ye get me?  \n\nNow you just leave me be and go get lost in The Forlorn Cavern.  That''s where you''ll find that warlock, Thistleheart.', `text1_1` = 'A warlock, eh...  Well, if you''ve got a mind to be doing that sort of thing around here then ye best keep yer demons on a leash $gboyo : girlie;.  I don''t like demons, but I love putting mah axe to them.  Ye get me?  \n\nNow you just leave me be and go get lost in The Forlorn Cavern.  That''s where you''ll find that warlock, Thistleheart.' WHERE `ID` = 2775;
        UPDATE `npc_text` SET `text1_0` = 'Kelstrum is a loudmouth and a braggart... and if that weren''t enough he''s also one of the most skilled warriors ye''ll ever meet!  \n\nI tell ye, if ye''re looking to be trained in the ways of a warrior, that''s who ye should be talking to.  I''m sure he can be found over in the Hall of Arms east of the Gates of Ironforge.', `text1_1` = 'Kelstrum is a loudmouth and a braggart... and if that weren''t enough he''s also one of the most skilled warriors ye''ll ever meet!  \n\nI tell ye, if ye''re looking to be trained in the ways of a warrior, that''s who ye should be talking to.  I''m sure he can be found over in the Hall of Arms east of the Gates of Ironforge.' WHERE `ID` = 2776;
        UPDATE `npc_text` SET `text1_0` = 'Yer looking for an Alchemy trainer are ye?  Just came from there, I did.  Ye''ll find Ms. Berryfizz over in Tinker Town where the gnomes gather.  \n\n::sigh:: ...why o'' why didn''t I take the blue potion.', `text1_1` = 'Yer looking for an Alchemy trainer are ye?  Just came from there, I did.  Ye''ll find Ms. Berryfizz over in Tinker Town where the gnomes gather.  \n\n::sigh:: ...why o'' why didn''t I take the blue potion.' WHERE `ID` = 2794;
        UPDATE `npc_text` SET `text1_0` = 'Are ye really askin'' me where the Blacksmith is?  Have ye not heard of The Great Forge!?  All our best blacksmiths gather there to craft their weapons and armor!  \n\nIt''s dead smack in the middle of Ironforge, and that''s where you''ll find one of our most brilliant blacksmiths, Bengus Deepforge.  ', `text1_1` = 'Are ye really askin'' me where the Blacksmith is?  Have ye not heard of The Great Forge!?  All our best blacksmiths gather there to craft their weapons and armor!  \n\nIt''s dead smack in the middle of Ironforge, and that''s where you''ll find one of our most brilliant blacksmiths, Bengus Deepforge.  ' WHERE `ID` = 2795;
        UPDATE `npc_text` SET `text1_0` = 'Och!  Ye should be careful what ye get enchanted $glad : lass;.  I had me mug enchanted so it wouldn''t spill a drop, but now I can''t drink from it!  Such a tragedy.  \n\nYou be sure to heed me advice when ye see Gimble.  He''ll be in his shop right by the Gryphon Master at The Great Forge.', `text1_1` = 'Och!  Ye should be careful what ye get enchanted $glad : lass;.  I had me mug enchanted so it wouldn''t spill a drop, but now I can''t drink from it!  Such a tragedy.  \n\nYou be sure to heed me advice when ye see Gimble.  He''ll be in his shop right by the Gryphon Master at The Great Forge.' WHERE `ID` = 2797;
        UPDATE `npc_text` SET `text0_0` = 'The tinkerer''s craft for you is it?  No doubt ye''ll want to go see Springspindle Fizzlegear in Tinker Town.  \n\nJust head east from the gates of Ironforge, or follow the sound of the explosions.', `text0_1` = 'The tinkerer''s craft for you is it?  No doubt ye''ll want to go see Springspindle Fizzlegear in Tinker Town.  \n\nJust head east from the gates of Ironforge, or follow the sound of the explosions.', `text1_0` = 'Oh, you''re looking for Springspindle Fizzlegear then.  Why that little gnome and his gadgets...  Let me tell you, if you''re going to his shop in Tinker Town, keep your hands to yourself and don''t pet any of his mechanical sheep!  \n\nExploding sheep... now why would you even make such a thing!?', `text1_1` = 'Oh, you''re looking for Springspindle Fizzlegear then.  Why that little gnome and his gadgets...  Let me tell you, if you''re going to his shop in Tinker Town, keep your hands to yourself and don''t pet any of his mechanical sheep!  \n\nExploding sheep... now why would you even make such a thing!?' WHERE `ID` = 2798;
        UPDATE `npc_text` SET `text1_0` = 'Oh, ye want to learn to pick some daisies do ye?  Ha!  I''m just teasing ye $gladdie : lass;.  \n\nA fine profession it is, and Reyna Stonebranch can show ye how it''s done.  She works at the Ironforge Physician on the southern side of The Great Forge.', `text1_1` = 'Oh, ye want to learn to pick some daisies do ye?  Ha!  I''m just teasing ye $gladdie : lass;.  \n\nA fine profession it is, and Reyna Stonebranch can show ye how it''s done.  She works at the Ironforge Physician on the southern side of The Great Forge.' WHERE `ID` = 2801;
        UPDATE `npc_text` SET `text0_0` = 'Do we have Mining trainers here?  Where do ye think ye are!?  \n\nWhy you''ll find one o'' the best miners in all Dun Morogh at Deepmountain Mining and Jewelcrafting on the northern side of The Great Forge.  There, Geofram Bouldertoe will show ye the true art of mining.', `text0_1` = 'Do we have Mining trainers here?  Where do ye think ye are!?  \n\nWhy you''ll find one o'' the best miners in all Dun Morogh at Deepmountain Mining and Jewelcrafting on the northern side of The Great Forge.  There, Geofram Bouldertoe will show ye the true art of mining.', `text1_0` = 'Well well!  You''ve come to the right place to learn Mining, $gboyo : girlie;!  Geofram Bouldertoe himself resides at Deepmountain Mining and Jewelcrafting.  Ye couldn''t ask for a better instructor than him.', `text1_1` = 'Well well!  You''ve come to the right place to learn Mining, $gboyo : girlie;!  Geofram Bouldertoe himself resides at Deepmountain Mining and Jewelcrafting.  Ye couldn''t ask for a better instructor than him.' WHERE `ID` = 2804;
        UPDATE `npc_text` SET `text1_0` = 'Ye might not know it, but in addition to being a skilled tailor, Jormund is also a slayer of giants!  Why he must have overheard a few of us sharing stories when he shouted that he''d killed seven with one blow!  \n\nYe should pay him a visit at his store on the north side of The Great Forge an'' see if he''ll tell ye the tale!', `text1_1` = 'Ye might not know it, but in addition to being a skilled tailor, Jormund is also a slayer of giants!  Why he must have overheard a few of us sharing stories when he shouted that he''d killed seven with one blow!  \n\nYe should pay him a visit at his store on the north side of The Great Forge an'' see if he''ll tell ye the tale!' WHERE `ID` = 2807;
