        UPDATE `npc_text` SET `text0_0` = 'Welcome to the front lines, $c.  While politicians may connive and scheme amongst themselves, they''ll find no such luxury afforded to them here.  This is the Bulwark, and we fight for our continued survival on a daily basis here.$B$BIf you''ve come here looking for a chance to prove yourself as a hero, then you''ll find plenty of opportunities to do so.', `text0_1` = '' WHERE `ID` = 3753;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 5 WHERE `ID` = 3759;
