        UPDATE `npc_text` SET `text0_0` = 'Heya mon.  Once I get my hands on a few more supplies, I fix ya right up!', `text0_1` = '' WHERE `ID` = 3794;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'The Emerald Circle welcomes you, $N.$B$BHopefully together we can help rejuvenate and protect this once-mighty forest. Many forces seek to destroy it from without... and within.$B$BDo not be persuaded by the power here--it will only corrupt you, like it has this entire land.' WHERE `ID` = 3807;
        UPDATE `npc_text` SET `text1_0` = 'Oh, the tram, the tram...  everyone wants to ride the tram.  What happened to the good ol'' days of flying on the back of a gryphon, gripping the saddle for dear life as you flew up high in the sky above?  \n\nBah!  You go take the tram then... it''s over in Tinker Town with the rest of the gnomish contraptions.', `text1_1` = 'Oh, the tram, the tram...  everyone wants to ride the tram.  What happened to the good ol'' days of flying on the back of a gryphon, gripping the saddle for dear life as you flew up high in the sky above?  \n\nBah!  You go take the tram then... it''s over in Tinker Town with the rest of the gnomish contraptions.' WHERE `ID` = 3814;
