        UPDATE `npc_text` SET `prob0` = 0, `prob1` = 0, `text2_0` = 'Nothing frees the spirit like soaring through the sky.  You may speak with Tak, the Wind Rider Master, in the center of the village, if you wish to soar through the air.', `text2_1` = 'Nothing frees the spirit like soaring through the sky.  You may speak with Tak, the Wind Rider Master, in the center of the village, if you wish to soar through the air.', `lang2` = 1, `prob2` = 1 WHERE `ID` = 4052;
        UPDATE `npc_text` SET `text0_0` = 'We don''t have a bank here in Brill, you''ll have to go to the Undercity for that.  At the back of the Ruins of Lordaeron to the south are elevators that will take you down into the Undercity.  Once there, ask one of the Undercity Guardians for more precise directions.', `text0_1` = 'We don''t have a bank here in Brill, you''ll have to go to the Undercity for that.  At the back of the Ruins of Lordaeron to the south are elevators that will take you down into the Undercity.  Once there, ask one of the Undercity Guardians for more precise directions.' WHERE `ID` = 4074;
        UPDATE `npc_text` SET `prob0` = 0, `prob1` = 0, `text2_0` = 'Looking to fly somewhere?  Anette Williams, in the western part of town, can get you there on one of her trained bats.', `text2_1` = 'Looking to fly somewhere?  Anette Williams, in the western part of town, can get you there on one of her trained bats.', `lang2` = 1, `prob2` = 1 WHERE `ID` = 4075;
        UPDATE `npc_text` SET `prob0` = 0, `prob1` = 0, `text2_0` = 'Innkeeper Renee has moved to the large building in the center of town.  It''s the biggest building in Brill... Very hard to miss.', `text2_1` = 'Innkeeper Renee has moved to the large building in the center of town.  It''s the biggest building in Brill... Very hard to miss.\n', `lang2` = 1, `prob2` = 1 WHERE `ID` = 4076;
        UPDATE `npc_text` SET `prob0` = 0, `prob1` = 0, `text2_0` = 'Do I look to you like I cast spells?  Well, I did hear that Cain Firesong now hangs out in the laboratory, always working on something unsavory.', `text2_1` = 'Do I look to you like I cast spells?  Well, I did hear that Cain Firesong now hangs out in the laboratory, always working on something unsavory.', `lang2` = 1, `prob2` = 1 WHERE `ID` = 4077;
