        UPDATE `npc_text` SET `text0_0` = 'Well met, friend.  I am Officer Garush, and I am a proud member of a world-wide organization known as the Argent Crusade.  Our cause is to fight swiftly and mercilessly against any element of evil that surfaces in Azeroth.  We are not a political body, nor do we ever wish to become one.  Our cause is singular, and to that end we call both the Horde and Alliance as friends - friends in the cause of stamping out evil!$B$BFor the Crusade, my $g brother : sister;!', `text0_1` = '' WHERE `ID` = 4134;
