        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Welcome! Step right up, don''t be shy.$b$bThis here is my pride and joy... the Blastenheimer 5000 Ultra Cannon! Ain''t she pretty?' WHERE `ID` = 7789;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'It''s simple! You give me a Darkmoon Game Token, and I toss you in and light the fuse.$B$BYou''ll "float" for a little while after you''re shot, but you can descend quickly by dropping the "wings" I''ll give you.$B$BYou''re aiming for a big floating target in the water right off the boardwalk.$B$BJust don''t drop your wings while you''re still over ground, or... well... I don''t sell life insurance!' WHERE `ID` = 7790;
        UPDATE `npc_text` SET `text0_0` = 'An excellent question! We have many things for sale here at the faire. If you are interested in food or drink, then visit Stamp or Sylannia''s booths.\n\nIf you''d rather purchase something more exotic, then Lhara may have just the thing for you. She specializes in rarities from all over the world.\n\nAnd then there is Flik running around here somewhere. If you can grab him he sells balls for throwing and frogs to keep as pets.', `text0_1` = 'An excellent question! We have many things for sale here at the faire. If you are interested in food or drink, then visit Stamp or Sylannia''s booths.\n\nIf you''d rather purchase something more exotic, then Lhara may have just the thing for you. She specializes in rarities from all over the world.\n\nAnd then there is Flik running around here somewhere. If you can grab him he sells balls for throwing and frogs to keep as pets.' WHERE `ID` = 7793;
        UPDATE `npc_text` SET `text0_0` = 'Glad you asked. Darkmoon Faire Prize Tickets are your currency to purchase some amazing prizes.$b$bPrize Tickets are rewarded for doing monthly quests and playing the games around the faire.$b$bCompleting the monthly quests will earn you the most Prize Tickets, but playing the games daily, is a great way to get ahead.$b$bOnce you have enough tickets, you can spend them at the different vendors on the faire grounds.', `text0_1` = 'Glad you asked. Darkmoon Faire Prize Tickets are your currency to purchase some amazing prizes.$b$bPrize Tickets are rewarded for doing monthly quests and playing the games around the faire.$b$bCompleting the monthly quests will earn you the most Prize Tickets, but playing the games daily, is a great way to get ahead.$b$bOnce you have enough tickets, you can spend them at the different vendors on the faire grounds.' WHERE `ID` = 7794;
