        UPDATE `npc_text` SET `text0_0` = 'Enjoying the festival, $c?$b$bWhile the Flame Wardens tend to the fires of the present, I am more of a historian, keeping close the festivals past. I''m also, of course, documenting this year''s festivities. Things are going well thus far, don''t you think?$b$bYou know, $n, there is power inherent in all festival fires burning throughout the holiday. We''re taking care of ours, but I''m certain there are sacred flames burning deep within our enemy''s cities...', `text0_1` = 'Enjoying the festival, $c?$b$bWhile the Flame Wardens tend to the fires of the present, I am more of a historian, keeping close the festivals past. I''m also, of course, documenting this year''s festivities. Things are going well thus far, don''t you think?$b$bYou know, $n, there is power inherent in all festival fires burning throughout the holiday. We''re taking care of ours, but I''m certain there are sacred flames burning deep within our enemy''s cities...' WHERE `ID` = 8703;
