        UPDATE `npc_text` SET `text0_0` = 'Thank goodness for you!  Claw and I were investigating this place when we were jumped by Swamplord Musel''ek.$B$BUnfortunately, Claw was caught in bear form at the time, and is now the swamplord''s pet.$B$BI''m afraid you''ll have to fight Claw in order to save him.', `text0_1` = '' WHERE `ID` = 9121;
