        UPDATE `npc_text` SET `text0_0` = 'Varos Cloudstrider and his ring guardians protect the second ring.  Your drakes are more than a match for the ring guardians, but Varos stands behind an impenetrable shield created from the energy of the Oculus itself.  Ten centrifuge constructs power the shield from the ring and platforms above.  Destroy them and Varos will be vulnerable.\n\nI can grant you the power to call upon a drake from the red fight.  Speak to Eternos or Verdisa if you prefer to draw on the power of the bronze or the green.', `text0_1` = '' WHERE `ID` = 12916;
        UPDATE `npc_text` SET `text0_0` = 'Belgaristrasz speaks the truth; time is running out!\n\nI can grant you the power to call upon a drake from the bronze flight.  Speak to Belgaristrasz or Verdisa if you prefer to draw on the power of the red or the green.', `text0_1` = '' WHERE `ID` = 12917;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 12929;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'The Infinite Dragonflight is attempting to alter the destiny of Prince Arthas Menethil.$B$BYou know him now as the Lich King, but here and now he was still a Prince of Lordaeron trying to do what was best for his kingdom.$B$BArthas makes a very fateful choice today, leading to something we Keepers of Time call an inflection point in the timeline.' WHERE `ID` = 12949;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Arthas gave the order to cull Stratholme, killing every single human within its walls.$B$BHe discovered evidence that the Scourge had infected the city with their insidious plague, and the disease doesn''t just kill people.$B$BThose who die to this plague rise up as mindless zombies, further fueling the Scourge''s war machine.' WHERE `ID` = 12950;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'The Infinites are attempting something unusually subtle for them. They are trying to hide the evidence that will lead to Arthas deciding to cull Stratholme.$B$BTheir agents have used illusionary magic on the plagued grain shipments in the nearby countryside to make them appear normal.$B$BI need you to find the hidden grain, and use this Arcane Disruptor on the shipments. Arthas'' men are looking for plagued grain, and should find it quickly with the illusion gone.' WHERE `ID` = 12952;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 5 WHERE `ID` = 12978;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Good work! Arthas now knows about the plagued grain in Stratholme, and is about to begin the culling.$B$BSomething is still not quite right, though. I sense a foreign presence in this timeline besides us, and that must mean the Infinite Dragonflight are here somewhere.' WHERE `ID` = 12992;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'I don''t know, and that worries me. I''ll do everything I can to find the Infinites.$B$BWhat I need you to do now is stay close to Arthas by joining his army.' WHERE `ID` = 12993;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Well, you''re not going to sign recruitment papers or anything, but you are going to fight alongside him.$B$BYou need to make sure Arthas culls Stratholme and defeats Mal''Ganis. Without Uther and Jaina around, he''ll need all the help he can get.$B$BIf you talk to Arthas, he''ll put you to work destroying the forces of Mal''Ganis. Follow along until I can figure out what''s going on with the Infinites.' WHERE `ID` = 12994;
        UPDATE `npc_text` SET `lang7` = 0 WHERE `ID` = 13022;
        UPDATE `npc_text` SET `text0_0` = 'Well now, I''m surprised to see other adventurers in a place such as this!$B$BNow that you''re here, ye can help me get to the Tribunal. If my research theories about these halls is correct, information pertainin'' to the creation o'' the entire dwarven race lies within.', `text0_1` = '' WHERE `ID` = 13100;
        UPDATE `npc_text` SET `text0_0` = 'If only my dear brothers could be here with me at this moment in time. They would not believe what a discovery this will be!$B$BThe Tribunal are the librarians for the Titan discs, which are stored in this very room.$B$BLook! You can see the discs beneath the floor! We must hurry, the greatest discovery of Dwarven kind is just up ahead.', `text0_1` = '' WHERE `ID` = 13101;
        UPDATE `npc_text` SET `text0_0` = 'Indeed. Mal''Ganis is commanding the Scourge from Crusaders'' Square, but the gates leading there from the city entrance are closed.$B$BLittle does he know that a small force can still reach the Square by moving through the Town Hall. Will you join me in this attack?', `text0_1` = '' WHERE `ID` = 13126;
        UPDATE `npc_text` SET `text0_0` = 'Ahunae''s axe will be the end of the Drakkari.$B$BYou be takin'' care of any that get past my axe!', `text0_1` = '' WHERE `ID` = 13234;
        UPDATE `npc_text` SET `text0_0` = 'There are two zeppelin towers outside Orgrimmar. The eastern tower serves Tirisfal Glades and Stranglethorn Vale, while the western tower serves Northrend and Thunder Bluff.', `text0_1` = 'There are two zeppelin towers outside Orgrimmar. The eastern tower serves Tirisfal Glades and Stranglethorn Vale, while the western tower serves Northrend and Thunder Bluff.', `prob0` = 0, `text1_0` = 'Which one?', `text1_1` = 'Which one?', `prob1` = 1, `em1_0_delay` = 0, `em1_0` = 396 WHERE `ID` = 13310;
        UPDATE `npc_text` SET `prob0` = 0, `text1_0` = 'I will mark the location upon your map.', `text1_1` = 'I will mark the location upon your map.', `prob1` = 1, `em1_0_delay` = 0, `em1_0` = 396 WHERE `ID` = 13311;
        UPDATE `npc_text` SET `lang7` = 0 WHERE `ID` = 13402;
