        UPDATE `npc_text` SET `lang7` = 0 WHERE `ID` = 13454;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'What are you doing all the way back here? You need to get back to Stratholme immediately!$B$BShall I teleport you to Stratholme?' WHERE `ID` = 13470;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Go find those hidden plagued grain crates and use your Arcane Disruptor on them!$B$BArthas will then have the evidence he needs to begin the culling of Stratholme.' WHERE `ID` = 13471;
