        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'That''s right, I''ve seen you here before! How could I forget?$B$BI can teleport you to Stratholme now, if you wish.' WHERE `ID` = 15704;
        UPDATE `npc_text` SET `text0_0` = 'You... WHAT?$B$BCome over here and say that!$B$B<Kristoff kicks and flails his limbs in a frothing rage, his head twisting around to glare at you.>$B$BSo help me, I will - I am going to - I will knock your brains out! I will fill the empty cavity left behind with my boot! Come here! GET BACK HERE!$B$B<Kristoff strains to grasp your neck, his fingers wriggling inches from your face.>', `text0_1` = NULL, `prob0` = 1, `em0_0_delay` = 0, `em0_0` = 5, `em0_1_delay` = 0, `em0_1` = 15 WHERE `ID` = 15739;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 15755;
        UPDATE `npc_text` SET `text0_0` = 'Destroyed? Yes, that''s possible. At night I am haunted with visions of this world being torn asunder from within. I feel neither sorrow nor rage. Merely... curiosity.$B$BI served my master in exchange for power, $c. But those you fight... they strive for oblivion. A strange motivation.', `text0_1` = '' WHERE `ID` = 15781;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1, `em1_0_delay` = 0, `em1_0` = 15, `em2_0_delay` = 0, `em2_0` = 6, `em3_0_delay` = 0, `em3_0` = 6 WHERE `ID` = 15829;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 15845;
