        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'The Frost Lord, Ahune, must be stopped.\n\nEven now he is taking form, summoned from his elemental prison by the mad cultists of the Twilight''s Hammer.\n\nIf he''s allowed to enter our world completely, he''ll bury us beneath an eternal winter.' WHERE `ID` = 15855;
