        UPDATE `npc_text` SET `text1_0` = '<The injured soldier appears to still be breathing. Thankfully, his bubble remains intact.>', `text1_1` = '<The injured soldier appears to still be breathing. Thankfully, her bubble remains intact.>', `text3_0` = '<It looks as if this solider might be feigning to throw off naga suspicion. It likely saved his life.>', `text3_1` = '<It looks as if this solider might be feigning to throw off naga suspicion. It likely saved her life.>' WHERE `ID` = 16019;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'I have dispatched Arch Druid Hamuul Runetotem to the burned out husk of the Sanctuary of Malorne. He is behind the front lines, on scorched terrain known as the Flamewake. He is looking into how we can undo the damage, and investigating the whereabouts of the turtle ancient Tortolla.$B$BBut before you can help him, you must first ensure that the Shrine of Aessina to the west is secure and the animals are saved from the flames. Otherwise all is lost! Concentrate on matters at the Grove of Aessina first, and they will send you to the Arch Druid in good time.' WHERE `ID` = 16040;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 16072;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 16089;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1, `em0_1_delay` = 0, `em0_1` = 1 WHERE `ID` = 16094;
        UPDATE `npc_text` SET `text0_0` = 'In all my days, $r, I''ve never seen such a thing...', `text0_1` = '' WHERE `ID` = 16097;
        UPDATE `npc_text` SET `text0_0` = 'Welcome, friend.\n\nWe have little to offer by way of supplies, but I will assist you however I can.', `text0_1` = '' WHERE `ID` = 16108;
        UPDATE `npc_text` SET `text0_0` = 'The Earthwatchers won''t allow faction squabbling to jeopardize the Earthen Ring''s work here.\n\nThose who break the peace will be dealt with... harshly.', `text0_1` = '' WHERE `ID` = 16122;
        UPDATE `npc_text` SET `text0_0` = 'The Wildhammers have always embraced shamanism, aye, but to find ourselves beneath the sea as part of the Earthen Ring?\n\nIt would''ve taken more than a few tankards for me to believe that one, a year ago.', `text0_1` = '' WHERE `ID` = 16125;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 6 WHERE `ID` = 16143;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 5 WHERE `ID` = 16144;
        UPDATE `npc_text` SET `text0_0` = 'Operation: Gnomeregan was a success. Sure, that dastardly Thermaplugg had an unforeseen trick up his sleeve, but we have him on the run! It''s only a matter of time before Gnomeregan is cleaned up and in our hands again!', `text0_1` = '' WHERE `ID` = 16215;
