        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 16247;
        UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'In my youth, my family did not approve of my interest in shamanism. Brash and foolish as I was, I ran away from them and practiced on my own.  Upon returning to my home one day, I found my parents gone. My home destroyed. They never found who did it.\n\nI''ve spent my life striving to extend my shamanistic visions to see into the past - to find out what happened to my family and who is responsible. I''ve come a great way. I''ve learned to focus in on impactful events in the recent past, but I have much further to go if I ever hope to glimpse something that occurred so long ago.' WHERE `ID` = 16270;
