        UPDATE `npc_text` SET `text0_0` = 'Throm-Ka, $N. We snuck a few more in while you were preparing the Gates for attack.$B$BI''ll show you where we''re to meet with Garona.$B$B<The squad leader produces a map of the Twilight Citadel and points to the spot.>$B$BLet me know when you''re ready, and we''ll go together.', `text0_1` = '' WHERE `ID` = 16974;
        UPDATE `npc_text` SET `em0_0_delay` = 0, `em0_0` = 1 WHERE `ID` = 16991;
