        UPDATE `npc_text` SET `text0_0` = 'The Earthen Ring have set up portals to various regions of the world on the cliffs north of the zeppelin towers.\n\nThere are representatives from Hellscream''s Reach there as well, offering transport to Tol Barad.', `text0_1` = 'The Earthen Ring have set up portals to various regions of the world on the cliffs north of the zeppelin towers.\n\nThere are representatives from Hellscream''s Reach there as well, offering transport to Tol Barad.' WHERE `ID` = 17203;
        UPDATE `npc_text` SET `text0_0` = 'A trio of ethereal technomancers has set up shop in Orgrimmar, along the eastern Drag.\n\nLook for the weird machinery and purple lights... you can''t miss it.\n\nThey offer just the sort of services you''re looking for.', `text0_1` = 'A trio of ethereal technomancers has set up shop in Orgrimmar, along the eastern Drag.\n\nLook for the weird machinery and purple lights... you can''t miss it.\n\nThey offer just the sort of services you''re looking for.' WHERE `ID` = 17204;
