        UPDATE `npc_text` SET `text0_0` = 'Here you see the Darkmoon Deathmatch pit.  Do you possess the power and will to best all comers and take the pit fighter''s prize?\n\nBouts begin at midnight and every three hours thereafter.', `text0_1` = '' WHERE `ID` = 18472;
        UPDATE `npc_text` SET `text0_0` = 'I see you''ve arrived. \n$bThis is the eve of the sundering, when the collapse of the Well of Eternity fractured the continents of the world.\n$bHere, we will snatch up the Dragon Soul before it is lost to the mists of time.\n$bBut first, you must bring down the protective wards of Azshara''s lackeys. You will find them within the palace. I will scout on ahead.\n$bGood luck, heroes!', `text0_1` = '' WHERE `ID` = 18514;
        UPDATE `npc_text` SET `text0_0` = 'The shadows will hide us well.\n$bI am concealed by this shadowcloak, and can imbue its magics onto you.\n$bIt will not make us invisible, but as long as we keep our distance from our foes we will remain hidden.', `text0_1` = '' WHERE `ID` = 18550;
        UPDATE `npc_text` SET `text0_0` = 'Anything outside of that circle around you will not be able to see you, but the illusion will fade if you attack or take damage.\n$bI suggest you remain hidden until I say otherwise, these demons are too powerful to face head on and in full force.', `text0_1` = '' WHERE `ID` = 18551;
